  'The syllabus includes category management, market intelligence, total cost of ownership, RFx design, negotiation game planning, contract governance, global trade risk, responsible sourcing, digital procurement, supplier development, and a full strategic sourcing capstone.',
  $procjson${"slug": "procurement-and-sourcing", "title": "Procurement and Sourcing", "description": "The syllabus includes category management, market intelligence, total cost of ownership, RFx design, negotiation game planning, contract governance, global trade risk, responsible sourcing, digital procurement, supplier development, and a full strategic sourcing capstone.", "topics": [{"id": "d98db48b-e474-44c0-ac28-1e7a15f5f029", "type": "topic", "title": "Procurement and Strategic Sourcing as a Supply Chain Value System", "description": "Position procurement as a strategic capability that shapes cost, risk, innovation, resilience, sustainability, and customer value across the supply chain.", "children": [{"id": "780263c2-59a1-47b5-b856-9190946fd4c6", "type": "subtopic", "title": "Procurement's strategic role", "children": [{"id": "4405c768-a239-476c-a57e-db9f62594737", "type": "concept", "title": "Cost, quality, service, risk, innovation, and ESG value"}, {"id": "0e4a0e6e-f3e6-483f-aa3c-06a28a3f1513", "type": "concept", "title": "Procurement's links to operations, finance, legal, engineering, and sustainability"}, {"id": "282b902f-ea09-4785-aaff-77cd8a4d9d65", "type": "concept", "title": "Source-to-pay versus strategic sourcing"}, {"id": "f98089a7-8e50-4237-9a1b-8fe12b2867b5", "type": "concept", "title": "Procurement as a supply-chain coordination function"}], "description": "This subtopic reframes procurement from transaction handling into a leadership function that can shape enterprise outcomes."}, {"id": "d11ab77b-127f-4b1f-bbf2-60cd9a54b04a", "type": "subtopic", "title": "Supply-chain value architecture", "children": [{"id": "d2e98673-3e99-47a5-a142-74071f2aeb0e", "type": "concept", "title": "Plan-source-make-deliver-return logic"}, {"id": "84e98b9f-fb35-4e91-8c94-d1fcf1c77a90", "type": "concept", "title": "Supplier tiering and upstream dependencies"}, {"id": "677e8c3e-eebe-4f02-a793-ef1e256960b5", "type": "concept", "title": "Cost-service-resilience tradeoffs"}, {"id": "9a72298c-a4de-4983-8573-bd1f1b9bac88", "type": "concept", "title": "Value stream and process mapping"}], "description": "Students learn how sourcing decisions influence the wider supply chain, not just the price paid to a vendor."}, {"id": "2827b183-b15d-4c27-870c-68a1065253f4", "type": "subtopic", "title": "Governance and maturity", "children": [{"id": "497b3158-9aba-41e9-9862-0dd985840234", "type": "concept", "title": "Policy, delegation of authority, and approval thresholds"}, {"id": "5f1f8884-f141-45bb-a5f1-f95d68b37ee9", "type": "concept", "title": "Center-led, centralized, decentralized, and hybrid models"}, {"id": "5458e1fe-71ea-4743-9553-7386a739628b", "type": "concept", "title": "Procurement KPIs and scorecards"}, {"id": "98fd652b-54b4-433a-a4d1-e5773ccc4b07", "type": "concept", "title": "Stakeholder trust and service-level expectations"}], "description": "Procurement maturity models help students diagnose whether an organization is reactive, controlled, strategic, or transformational."}]}, {"id": "73884114-ded5-4742-ad7c-08158e4982d4", "type": "topic", "title": "Purchasing Process, Procure-to-Pay, and Procurement Operating Models", "description": "Build fluency in the process architecture that turns business needs into compliant purchases, payment, controls, and measurable service.", "children": [{"id": "3849eec2-8a7f-48d5-b6e6-8f7c5c287c73", "type": "subtopic", "title": "Purchasing workflow", "children": [{"id": "91b99425-008d-4b4f-9961-b7f808d75956", "type": "concept", "title": "Requisitions and approvals"}, {"id": "55e35b1e-09a8-4198-a63c-8008bfdb644c", "type": "concept", "title": "Purchase orders and blanket orders"}, {"id": "08f42787-f76b-4dff-901e-6466fd43ec97", "type": "concept", "title": "Receiving, three-way match, and invoice handling"}, {"id": "d8e0c3cc-0c51-488b-980d-53606d31d9f6", "type": "concept", "title": "Exception management and cycle-time control"}], "description": "The basic workflow shows how business requests become purchase orders, receipts, invoices, and payment."}, {"id": "43575a62-3663-43aa-946a-79635136b675", "type": "subtopic", "title": "Procure-to-pay controls", "children": [{"id": "9e9c4c1c-bd8b-4c98-839d-45cb505ce81a", "type": "concept", "title": "Segregation of duties"}, {"id": "706d13e0-0a3b-4145-8358-1a462feaefc2", "type": "concept", "title": "Preferred supplier and catalog compliance"}, {"id": "223eb226-7a76-47b8-805d-50ec7131e2e7", "type": "concept", "title": "Audit trails and documentation"}, {"id": "7d6b33e3-6fac-49e4-bef1-80fd9261673f", "type": "concept", "title": "Fraud red flags and internal control testing"}], "description": "Controls protect the organization from fraud, maverick spend, policy violations, and weak financial discipline."}, {"id": "51b10b12-512a-4ff3-8c9a-13d88c34e560", "type": "subtopic", "title": "Operating models and service design", "children": [{"id": "dc73f362-b333-4dfa-aebe-bb671b2c2cf2", "type": "concept", "title": "Category teams and business partnering"}, {"id": "bc24c4e4-9909-498d-99e2-b78f3061ac8d", "type": "concept", "title": "Shared services and help desks"}, {"id": "2ee56ebc-6b47-4122-a8f4-f10698ef59eb", "type": "concept", "title": "Centers of excellence"}, {"id": "090ef8ed-bc0e-4403-bcd1-68ec1b1d1a6b", "type": "concept", "title": "Service-level agreements and intake channels"}], "description": "Operating model choices determine how procurement serves business units while maintaining consistency and expertise."}]}, {"id": "32d3f9aa-2108-45eb-9794-42562e5da6fb", "type": "topic", "title": "Spend Analysis, Category Management, and Opportunity Assessment", "description": "Use data to understand what the organization buys, who it buys from, where value leaks occur, and which categories deserve focused sourcing attention.", "children": [{"id": "ccedb066-8437-45e2-ab03-b54e0501a593", "type": "subtopic", "title": "Spend visibility", "children": [{"id": "abd58693-3030-4dd9-bc45-22b4fc2db85d", "type": "concept", "title": "Data extraction and cleansing"}, {"id": "911959b3-18ba-4b76-aa21-42a3d83edb70", "type": "concept", "title": "Supplier normalization"}, {"id": "9b3b9cef-8239-4d89-b5fd-cffd1aeab273", "type": "concept", "title": "Commodity and UNSPSC-style classification"}, {"id": "2bfb530b-2adb-4363-a31c-053b8de036ec", "type": "concept", "title": "Tail spend and maverick spend"}], "description": "Spend visibility is the evidence base for nearly every serious sourcing decision."}, {"id": "e974dba4-2bc7-4f66-9c48-6d22f5f3ceb0", "type": "subtopic", "title": "Category strategy", "children": [{"id": "6ba1240a-0280-4be3-b19b-90703080bf0f", "type": "concept", "title": "Category profiling"}, {"id": "bfedc042-76af-4bbc-97b5-4b9c30516193", "type": "concept", "title": "Demand analysis and stakeholder mapping"}, {"id": "5ea054f1-07df-45e8-971b-56cb93767fb7", "type": "concept", "title": "Kraljic-style portfolio thinking"}, {"id": "5d586f33-4fe4-4998-8837-0e1504b08c72", "type": "concept", "title": "Strategic, leverage, bottleneck, and routine categories"}], "description": "Category management groups purchases into markets with similar suppliers, demand patterns, risks, and value levers."}, {"id": "149897b5-d380-4978-b737-73e6edc690b3", "type": "subtopic", "title": "Opportunity assessment", "children": [{"id": "95498de9-199b-4ee3-b7a1-1a67128db7a9", "type": "concept", "title": "Baseline spend and savings logic"}, {"id": "dc2dc922-be12-4ea9-810f-7b7a67f57de5", "type": "concept", "title": "Price, demand, specification, process, and compliance levers"}, {"id": "e785bb97-1eac-43e7-891b-3d31fc3bc01b", "type": "concept", "title": "Savings validation with finance"}, {"id": "7592aaeb-4475-43dd-a1f0-f6c324ecf4fb", "type": "concept", "title": "Opportunity pipeline and wave planning"}], "description": "Opportunity assessment helps prioritize sourcing work by value, feasibility, urgency, and organizational readiness."}]}, {"id": "d7772c68-7b6e-414e-9a8a-10219514cc0c", "type": "topic", "title": "Supplier Markets, Market Intelligence, and Make-Buy Decisions", "description": "Analyze supply markets, industry structure, supplier economics, and internal capability choices before launching sourcing work.", "children": [{"id": "bdc1a0ee-e086-47fd-babc-5d8ed0a4ca80", "type": "subtopic", "title": "Supply-market analysis", "children": [{"id": "3d8a7730-3161-4383-b4f1-cefe54d3e993", "type": "concept", "title": "Supplier landscape and market concentration"}, {"id": "1c3f85cb-6a3a-449b-b64d-accddc181a8c", "type": "concept", "title": "Porter's five forces for supply markets"}, {"id": "09ccfddc-9381-49a1-98ef-74b1541ccc22", "type": "concept", "title": "Capacity, lead time, and technology trends"}, {"id": "ce4ef20c-dd51-452e-ae10-fb61d4bf458e", "type": "concept", "title": "Commodity indices and market signals"}], "description": "Students learn to read supplier markets before assuming competition, capacity, or price power exists."}, {"id": "d37d4ac1-2801-456b-b498-1e2693a3b717", "type": "subtopic", "title": "Supplier economics", "children": [{"id": "19736f7f-06b7-47f4-a9cd-c7738e570213", "type": "concept", "title": "Cost structure and margin logic"}, {"id": "d418d4cf-0ffd-45f2-8214-c00a8381d089", "type": "concept", "title": "Fixed versus variable cost"}, {"id": "7ad19c35-d1f5-4a0f-bb89-101437bdb417", "type": "concept", "title": "Learning curves and scale effects"}, {"id": "8f9f58a3-05ef-492d-9699-fed376908e53", "type": "concept", "title": "Supplier financial health"}], "description": "Understanding supplier economics helps buyers negotiate realistically and build offers that can be sustained."}, {"id": "2717f6a0-278c-49ed-bd4d-20c9032e13f4", "type": "subtopic", "title": "Make-buy and outsourcing choices", "children": [{"id": "d702d28c-69d9-4430-9f05-0db60e494a24", "type": "concept", "title": "Core competence and strategic control"}, {"id": "e207faad-0af4-4b56-99a8-f53850b911ca", "type": "concept", "title": "Transaction-cost economics"}, {"id": "a4226819-04ac-42bd-b6dc-6971a78481b1", "type": "concept", "title": "Capacity, quality, and intellectual property concerns"}, {"id": "6a262618-f6a5-48bf-b25b-bb0b696e50d1", "type": "concept", "title": "Outsourcing, insourcing, and co-sourcing models"}], "description": "Make-buy decisions clarify what should remain internal, what can be outsourced, and what capabilities require close governance."}]}, {"id": "b78f818e-0a67-46c5-af41-99a61a2b3625", "type": "topic", "title": "Requirements, Specifications, and Total Cost of Ownership", "description": "Translate stakeholder needs into clear specifications and complete cost models that support smarter commercial decisions.", "children": [{"id": "68881a4e-ce74-4709-b2f1-cfb0485da67b", "type": "subtopic", "title": "Requirements discovery", "children": [{"id": "0f82ac60-015e-4c51-89cc-2abd1e92e606", "type": "concept", "title": "Voice of stakeholder and voice of customer"}, {"id": "9a1498f3-fb96-44fa-bd6f-a454f2677b03", "type": "concept", "title": "Functional versus technical requirements"}, {"id": "cfd184f8-ce64-4e61-ad8f-02b300692d45", "type": "concept", "title": "Service levels and performance outcomes"}, {"id": "efefe2a7-1569-487a-8c23-194870bd385e", "type": "concept", "title": "Demand management and standardization"}], "description": "Good sourcing starts with understanding the real business need, not merely repeating last year's specification."}, {"id": "ced4b326-c754-41fb-99ec-1d9d511d2627", "type": "subtopic", "title": "Specification strategy", "children": [{"id": "eb13837a-5515-4ef8-9bba-2f10ab3725d1", "type": "concept", "title": "Design specifications"}, {"id": "db92e050-331d-4bbb-ae85-ce7b1ca303b5", "type": "concept", "title": "Performance specifications"}, {"id": "d2ec231f-d86e-4880-9536-ea6f6651c6c9", "type": "concept", "title": "Statements of work"}, {"id": "eb964347-21fc-483d-99bd-542cd8966a98", "type": "concept", "title": "Specification lock-in and over-specification"}], "description": "Specification choices influence competition, innovation, cost, and supplier accountability."}, {"id": "f85115f1-f1b3-42c5-8c73-d8dd810d20c8", "type": "subtopic", "title": "Total cost of ownership", "children": [{"id": "5bd309f8-d0bf-4d71-99e5-cbae78eb67e6", "type": "concept", "title": "Acquisition, operating, maintenance, logistics, quality, and disposal costs"}, {"id": "10a4c465-6515-413e-bbcd-95cece59fc93", "type": "concept", "title": "Switching costs and transition costs"}, {"id": "3089eba2-2c11-42d0-bfec-d3ed0bda4c6b", "type": "concept", "title": "Landed cost and tariff effects"}, {"id": "62d6a64b-87ab-4c26-8c8f-7ba239f3c2fa", "type": "concept", "title": "Cost sensitivity and scenario analysis"}], "description": "TCO prevents teams from mistaking the lowest unit price for the best business decision."}]}, {"id": "cdf9e4f4-08e7-4c02-b787-b3a815a4c89c", "type": "topic", "title": "Supplier Identification, Qualification, and Selection", "description": "Develop disciplined methods for finding, screening, evaluating, and selecting suppliers that fit cost, quality, risk, and strategic goals.", "children": [{"id": "6642cd8a-132b-4333-8b83-918a84b96bab", "type": "subtopic", "title": "Supplier discovery", "children": [{"id": "03b83d61-288f-4cf9-a30e-3a6e07c23e85", "type": "concept", "title": "Incumbents and challengers"}, {"id": "735c5970-e544-461e-bdf0-48f719ac6661", "type": "concept", "title": "Supplier databases and industry networks"}, {"id": "3ffd2cf0-9147-4126-9ded-cbe66d92d58b", "type": "concept", "title": "Diverse and local supplier discovery"}, {"id": "8d3ed460-1279-4522-9d24-e8ceb5ed80ee", "type": "concept", "title": "Long lists, short lists, and market sounding"}], "description": "Supplier discovery builds the candidate pool and determines whether the organization sees the full market."}, {"id": "186f1631-6baf-44cd-beec-1670a9350378", "type": "subtopic", "title": "Qualification and due diligence", "children": [{"id": "9219267b-93a3-4633-ae1c-8b5703c03d43", "type": "concept", "title": "Financial, operational, quality, and capacity checks"}, {"id": "1aba6e27-eb0b-4cae-9ee8-5e23addcd2f9", "type": "concept", "title": "Cyber, data, and privacy review"}, {"id": "b8454f9a-cb18-4a07-a5e1-42a4a4580d99", "type": "concept", "title": "Sanctions, legal, and ethical screening"}, {"id": "49183368-03f4-4a31-9f5a-e7aa0b26045e", "type": "concept", "title": "Site visits, audits, and references"}], "description": "Qualification verifies whether suppliers are capable, compliant, financially sound, and aligned with risk expectations."}, {"id": "0b6e8441-f79e-4083-b17b-86fc6795d7c4", "type": "subtopic", "title": "Selection methods", "children": [{"id": "23acc950-e729-46f9-954f-a694b3746fc2", "type": "concept", "title": "Weighted scoring models"}, {"id": "cb17ea46-be21-445d-8242-f48edb07a8de", "type": "concept", "title": "Technical and commercial evaluation"}, {"id": "da585b62-886f-4f57-b071-63355a73592a", "type": "concept", "title": "Best-value versus lowest-price selection"}, {"id": "47ad656c-1137-43ad-a94a-366597eba91c", "type": "concept", "title": "Consensus scoring and decision governance"}], "description": "Selection turns qualitative and quantitative evidence into defensible award decisions."}]}, {"id": "805cd85b-b67c-477a-896e-ea11712927e6", "type": "topic", "title": "RFx, Auctions, Bid Evaluation, and Source-to-Contract", "description": "Learn the formal sourcing tools used to invite competition, compare offers fairly, and move from market engagement to award decisions.", "children": [{"id": "a0965f2b-93de-4394-adc1-0019945c8722", "type": "subtopic", "title": "RFx design", "children": [{"id": "77ac2471-3212-4c87-8824-544f38f7fa22", "type": "concept", "title": "Request for information"}, {"id": "d8e39225-81c4-4dc8-b34d-7919f574baac", "type": "concept", "title": "Request for proposal"}, {"id": "db1a22d2-115a-4563-94d0-5a4cc973772c", "type": "concept", "title": "Request for quotation"}, {"id": "d7704d7a-d6ec-4971-940a-5a76d4560d4a", "type": "concept", "title": "Request for tender and sealed bids"}], "description": "RFx tools structure supplier communication and competition, but each format has a different purpose."}, {"id": "15401ca9-4ab6-433e-811b-65b4c5f8b519", "type": "subtopic", "title": "Competitive event mechanics", "children": [{"id": "c6092c3d-928c-4ecc-b46d-c2d6a23800c0", "type": "concept", "title": "Bid calendars and bidder conferences"}, {"id": "ecb57448-1a90-4f17-a366-9cc9ca4abb0b", "type": "concept", "title": "Clarifications and addenda"}, {"id": "a40011a6-71da-43a8-aad1-1f8f87accf04", "type": "concept", "title": "Reverse auctions"}, {"id": "94bf23e3-eb0b-469e-a30b-5b4663c178e4", "type": "concept", "title": "Fairness, confidentiality, and conflict of interest controls"}], "description": "Students learn when competition improves outcomes and when it can damage quality, trust, or supply security."}, {"id": "8715ab28-394f-440e-bebc-ff9ea3d4d547", "type": "subtopic", "title": "Source-to-contract execution", "children": [{"id": "d9fe6235-a7f6-4794-af84-353b95a07801", "type": "concept", "title": "Bid evaluation matrices"}, {"id": "330ed6ee-3f8b-40fc-ad2e-def1a2924e20", "type": "concept", "title": "Award scenarios and optimization"}, {"id": "514ccc8b-aee2-4071-a23a-fa259a3f168d", "type": "concept", "title": "Negotiation down-selects"}, {"id": "0b575112-fda4-4ea3-b05d-b1c14687bc12", "type": "concept", "title": "Contract handoff and implementation planning"}], "description": "Source-to-contract is the disciplined handoff from sourcing strategy to award, contracting, and implementation."}]}, {"id": "780e6597-872c-4174-b360-282cc12a5011", "type": "topic", "title": "Negotiation Strategy, Game Planning, and Supplier Economics", "description": "Prepare sourcing negotiations through interests, alternatives, cost drivers, power, ethics, and relationship goals.", "children": [{"id": "5b965032-2ae6-4606-a743-cf3abcd23dad", "type": "subtopic", "title": "Negotiation preparation", "children": [{"id": "f8ac6cd0-96f6-4f1e-919c-d076c4065254", "type": "concept", "title": "Interests, positions, and objectives"}, {"id": "a1976eaf-1727-4410-a7ff-231149121c97", "type": "concept", "title": "BATNA and walk-away points"}, {"id": "7d009f8d-84e2-45e0-a936-35707c97be55", "type": "concept", "title": "Issue lists and concession planning"}, {"id": "f944d9af-9feb-4d86-ba76-ec5a72855ef0", "type": "concept", "title": "Stakeholder alignment and negotiation mandate"}], "description": "Preparation determines the quality of the conversation before the first meeting happens."}, {"id": "7f36091e-50c1-4373-91b4-285c690abca9", "type": "subtopic", "title": "Commercial negotiation tactics", "children": [{"id": "dbf62945-99f7-4e81-ad64-c74f0e207f48", "type": "concept", "title": "Anchoring and framing"}, {"id": "2f68fb71-4ee5-4b06-8d8b-04f6cc4f7a42", "type": "concept", "title": "Package trades and logrolling"}, {"id": "ae1037d3-975c-416c-bae2-1e5f05812c21", "type": "concept", "title": "Should-cost arguments"}, {"id": "39fefa6c-f983-42cd-8d06-480358e040b0", "type": "concept", "title": "Multi-round negotiation strategy"}], "description": "Students practice concrete tactics while learning to avoid manipulative or unethical behavior."}, {"id": "a3eca6a3-cdf1-4277-9f07-120f7844534a", "type": "subtopic", "title": "Relationship and cross-cultural negotiation", "children": [{"id": "f6fdbef4-d271-4061-9897-ee0c9b1903fa", "type": "concept", "title": "Trust, credibility, and tone"}, {"id": "cc554715-2390-4f77-83e2-bb8897fcdcd3", "type": "concept", "title": "Cultural differences in negotiation norms"}, {"id": "157e6677-845c-4652-9b29-e0a393a608ec", "type": "concept", "title": "Difficult conversations and impasse management"}, {"id": "89f53452-96ba-4f27-96ea-51bbb8caf99b", "type": "concept", "title": "Ethics, transparency, and documentation"}], "description": "Procurement negotiations must often preserve long-term collaboration while still defending business interests."}]}, {"id": "db61482a-c905-425a-9be3-ec095e5ecffb", "type": "topic", "title": "Contracts, Commercial Terms, Risk Allocation, and Compliance", "description": "Understand how procurement agreements convert sourcing decisions into enforceable obligations, protections, incentives, and governance.", "children": [{"id": "38e6ec5b-6157-44b2-8623-34966113b8fb", "type": "subtopic", "title": "Contract structure", "children": [{"id": "904630be-913b-4c1a-8ede-bbc62e103fbd", "type": "concept", "title": "Master service agreements"}, {"id": "6af77cb1-283b-4997-8ae5-fc978c39c2a7", "type": "concept", "title": "Statements of work"}, {"id": "4c29d5bb-1599-40ff-97bc-aeff77453498", "type": "concept", "title": "Purchase terms and conditions"}, {"id": "3278485d-c930-4680-9365-64823d5f9ca8", "type": "concept", "title": "Order of precedence and exhibits"}], "description": "Students learn the anatomy of procurement agreements so they can read risks and obligations intelligently."}, {"id": "691b845e-dfe0-4f75-816c-e302d6c837ed", "type": "subtopic", "title": "Commercial and legal terms", "children": [{"id": "35b68757-ee39-4489-8d83-9a44cad03750", "type": "concept", "title": "Pricing, payment, indexation, and escalation"}, {"id": "d37b4589-1b9d-4267-9ec3-35943aeb7a45", "type": "concept", "title": "Service levels and warranties"}, {"id": "83c43150-1a4b-431f-96f8-7805f7613f64", "type": "concept", "title": "Limitation of liability and indemnity"}, {"id": "91b58610-c976-43c0-bc7b-1e3eae4ef9d1", "type": "concept", "title": "Termination, renewal, and change control"}], "description": "Commercial terms allocate money, timing, risk, accountability, and remedies across the buyer-supplier relationship."}, {"id": "b283cf36-8b28-4a10-8148-4d498d638466", "type": "subtopic", "title": "Compliance and contract governance", "children": [{"id": "a46c50b4-b310-4c1a-90aa-5765fcc1d02e", "type": "concept", "title": "Contract lifecycle management"}, {"id": "4649e1e9-29f3-4282-85b6-efcee6c159ed", "type": "concept", "title": "Delegation, approval, and records retention"}, {"id": "00f5ba22-4514-41c3-bfc1-588f60436349", "type": "concept", "title": "Regulatory and audit obligations"}, {"id": "496be540-63ed-4257-bf1b-44b903f5acf2", "type": "concept", "title": "Dispute resolution and escalation paths"}], "description": "Governance keeps the contract alive after signature and reduces disputes, leakage, and compliance failures."}]}, {"id": "7a416d29-4ee3-4695-b45b-571428fafc8d", "type": "topic", "title": "Supplier Relationship Management and Supplier Performance", "description": "Move beyond award decisions into performance management, collaboration, issue resolution, and value creation across supplier relationships.", "children": [{"id": "ba584590-2494-434c-ac70-2a2b0653eb63", "type": "subtopic", "title": "Supplier segmentation", "children": [{"id": "af4508cc-a6ad-488b-8515-86451c6df003", "type": "concept", "title": "Strategic, preferred, transactional, and emerging suppliers"}, {"id": "52d5a7c7-7443-478f-b29b-bd301ffc0f08", "type": "concept", "title": "Spend, risk, innovation, and dependency criteria"}, {"id": "7b9226fd-cf79-4262-9077-3fd5901eeaf8", "type": "concept", "title": "Tiered governance"}, {"id": "85e8642d-1f54-4b28-8f0c-c7f1e0d91699", "type": "concept", "title": "Relationship charters"}], "description": "Not every supplier relationship deserves the same management model; segmentation directs attention where it matters most."}, {"id": "c0051f4d-046f-4497-bbef-477c451cae46", "type": "subtopic", "title": "Performance management", "children": [{"id": "fb8ccab1-acfa-4ca5-b44f-d84809a06607", "type": "concept", "title": "Supplier scorecards"}, {"id": "7b52095a-d65c-4f07-94f7-7d8a36d7c874", "type": "concept", "title": "OTIF, quality, cost, responsiveness, and innovation metrics"}, {"id": "de79b36f-58d3-4746-a3bc-16b9341b7e16", "type": "concept", "title": "Quarterly business reviews"}, {"id": "9d7399c6-230f-4a0b-b4d6-0a169f3e71a5", "type": "concept", "title": "Corrective and preventive action"}], "description": "Performance management converts expectations into metrics, reviews, corrective actions, and improvement work."}, {"id": "0f5e7dac-8742-4395-b30c-c7d00831afbf", "type": "subtopic", "title": "Collaboration and value creation", "children": [{"id": "feff2d33-d506-468e-8093-11b2faca4217", "type": "concept", "title": "Joint business planning"}, {"id": "d8f6182b-823a-4b18-8e66-657931d7b415", "type": "concept", "title": "Supplier innovation days"}, {"id": "99f89886-c139-43c0-9c21-cf3981f3ae88", "type": "concept", "title": "Cost reduction workshops"}, {"id": "8d4aa592-dd0e-43e8-afbb-31a8ae3c98ea", "type": "concept", "title": "Gainsharing and collaborative improvement"}], "description": "Strong supplier relationships can unlock innovation, resilience, and process improvements that competitive bidding alone cannot create."}]}, {"id": "13bd0c34-6313-4276-86e9-13a023c46d60", "type": "topic", "title": "Global Sourcing, Logistics Interfaces, and Trade/Geopolitical Risk", "description": "Connect sourcing choices to trade rules, country risk, logistics constraints, Incoterms, currency, and geopolitical exposure.", "children": [{"id": "9aebc8d2-1605-4831-ba4a-113057f65822", "type": "subtopic", "title": "Global sourcing strategy", "children": [{"id": "8f73da99-8f8a-4c16-9956-895933f92fad", "type": "concept", "title": "Offshoring, nearshoring, reshoring, and friend-shoring"}, {"id": "877081db-63a0-4efa-9ff9-11c7b59e0f37", "type": "concept", "title": "Country and supplier-country analysis"}, {"id": "b9005627-84eb-4900-b006-d682e307a5da", "type": "concept", "title": "Currency and inflation exposure"}, {"id": "1df89d32-630f-4bbe-aeab-f65ce0a0733e", "type": "concept", "title": "Global category strategy"}], "description": "Global sourcing expands options but introduces distance, uncertainty, compliance obligations, and coordination costs."}, {"id": "6fdce52a-c4d0-414c-8876-a3522b6e526e", "type": "subtopic", "title": "Trade and logistics interface", "children": [{"id": "ab05900f-7b7e-4515-968a-323111844baa", "type": "concept", "title": "Incoterms and transfer of responsibility"}, {"id": "53b1cccd-ed27-4db3-a399-b885edf856f9", "type": "concept", "title": "Customs documentation and classification"}, {"id": "b1f0d30c-84e0-4648-adf9-3e7f15a4e0af", "type": "concept", "title": "Duties, tariffs, and landed cost"}, {"id": "4aed9ac5-34b9-4f3f-97b4-578e20546af7", "type": "concept", "title": "Freight mode, lead time, and port risk"}], "description": "Procurement decisions must account for how goods physically and legally move across borders."}, {"id": "0caf241d-1cbe-4567-a385-b285fe38d4c6", "type": "subtopic", "title": "Geopolitical and disruption risk", "children": [{"id": "65db855e-1d7f-437c-aef1-30e5bb1612f0", "type": "concept", "title": "Sanctions and export controls"}, {"id": "3646631f-0684-4e0e-a520-380079755d8d", "type": "concept", "title": "Political instability and trade disputes"}, {"id": "631283ac-a1e4-4367-ad6d-d4a741da6092", "type": "concept", "title": "Natural disasters and climate exposure"}, {"id": "08b45ae4-287c-422c-9c37-2248b4334af9", "type": "concept", "title": "Dual sourcing and regional redundancy"}], "description": "Students learn to connect sourcing maps with events that can interrupt supply or change total cost suddenly."}]}, {"id": "ce29bf11-25d9-4661-b6c4-add1a5d05f13", "type": "topic", "title": "Ethical, Sustainable, Diverse, and Responsible Sourcing", "description": "Integrate labor standards, environmental impact, supplier diversity, traceability, and responsible business conduct into sourcing decisions.", "children": [{"id": "53b32d0d-f41b-4470-b3ff-7ff3f5c5eb4d", "type": "subtopic", "title": "Responsible sourcing principles", "children": [{"id": "e0d84cd1-f8f1-4434-8d52-486e650dca96", "type": "concept", "title": "Human rights and labor standards"}, {"id": "73f8ebe9-8ec5-4763-b5e5-b8c45cbada7f", "type": "concept", "title": "Forced-labor and child-labor due diligence"}, {"id": "d57a31cb-640e-40da-a5df-8781ec680828", "type": "concept", "title": "Anti-corruption and gifts policies"}, {"id": "5dcd5c3b-a09b-4831-b3c8-dbfecaf6ed87", "type": "concept", "title": "Responsible business conduct frameworks"}], "description": "Responsible sourcing asks procurement to account for the people, communities, and ecosystems behind purchased goods and services."}, {"id": "5eafc0b2-ed61-40a8-8d8b-985a0f389c8c", "type": "subtopic", "title": "Sustainable procurement", "children": [{"id": "df63a30c-079e-416c-b4be-52624c2459d4", "type": "concept", "title": "Scope 3 emissions and supplier data"}, {"id": "66f98f03-1af4-47d6-b63e-2bc51a177266", "type": "concept", "title": "Circular economy and reuse"}, {"id": "cf4610da-f97c-48c8-94d2-2348cd17ddf5", "type": "concept", "title": "Packaging, waste, and water impacts"}, {"id": "489ba03c-9380-4539-adb6-af1fc73bf850", "type": "concept", "title": "Life-cycle thinking and eco-labels"}], "description": "Sustainable procurement links supplier choices to emissions, materials, waste, circularity, and lifecycle impact."}, {"id": "9f69be72-bfd7-4eaf-acef-59f9130ffbb2", "type": "subtopic", "title": "Supplier diversity and inclusion", "children": [{"id": "967f300e-dd8f-402f-9bcc-3bad46b63b81", "type": "concept", "title": "Diverse supplier certification"}, {"id": "80c8355c-be92-448d-8c07-b86ba5b3dffd", "type": "concept", "title": "Inclusive sourcing targets"}, {"id": "5a3e1cb9-5cc5-4502-a83d-17dbd69f54da", "type": "concept", "title": "Second-tier diversity reporting"}, {"id": "8a5fc7c9-39d1-46c4-87cf-88767c676630", "type": "concept", "title": "Capacity building and fair access"}], "description": "Supplier diversity expands economic opportunity while strengthening market access, innovation, and community impact."}]}, {"id": "5f228d85-8647-458a-b4bc-d5ad52ab1df7", "type": "topic", "title": "Procurement Analytics, Cost Modeling, and Digital Procurement", "description": "Use analytical models, digital platforms, automation, and dashboards to improve spend visibility, sourcing decisions, and procurement execution.", "children": [{"id": "bce3b5fb-bead-4641-b47e-0ac2db3880ff", "type": "subtopic", "title": "Cost and price analytics", "children": [{"id": "acf983c0-37ff-47c4-aba3-90995f02eee9", "type": "concept", "title": "Should-cost modeling"}, {"id": "6c70406a-bbd0-4a5c-9818-4a057a984817", "type": "concept", "title": "Price variance analysis"}, {"id": "710df2b8-f77a-4ab5-8364-fadd54f63949", "type": "concept", "title": "Index-based pricing"}, {"id": "2bc679b1-442c-432d-8bc6-6d9c0c949c28", "type": "concept", "title": "Regression and benchmarking"}], "description": "Analytics equips students to challenge quotes, explain cost movements, and build evidence-based recommendations."}, {"id": "ff971895-58aa-4428-82f4-609710da1d35", "type": "subtopic", "title": "Digital procurement platforms", "children": [{"id": "e811a015-b2b6-44cf-b3ff-1ec6aca15a60", "type": "concept", "title": "eSourcing tools"}, {"id": "f221e4fe-ada5-4b3c-9449-96870c197ca0", "type": "concept", "title": "Contract lifecycle management"}, {"id": "449ac442-73f1-4286-8c0c-c5da11eab4aa", "type": "concept", "title": "Supplier information management"}, {"id": "bf4d10d7-5463-401a-99a2-e44267bd270a", "type": "concept", "title": "Procure-to-pay and ERP integration"}], "description": "Digital platforms coordinate sourcing, contracting, supplier data, buying channels, and performance management."}, {"id": "83fc1b52-0153-4103-8a18-164b99019c25", "type": "subtopic", "title": "Automation, AI, and dashboards", "children": [{"id": "b6f77bac-ae8f-4465-bd9b-2e8cf71f399f", "type": "concept", "title": "Spend dashboards and savings trackers"}, {"id": "798cd6ad-b04e-4112-b1f0-548d903a01b9", "type": "concept", "title": "Risk monitoring feeds"}, {"id": "010d729c-8be6-4d4d-81a0-2e38aee62604", "type": "concept", "title": "Process mining and automation"}, {"id": "f5ceba76-5eec-4106-b26e-d2f09c96f7ef", "type": "concept", "title": "Generative AI use cases and governance"}], "description": "Modern procurement increasingly depends on decision support, automation, and control-tower visibility."}]}, {"id": "1300ece0-c627-4407-9cd9-d4dc01527824", "type": "topic", "title": "Risk, Resilience, Continuity, and Supplier Development", "description": "Identify supplier and supply-market vulnerabilities, design continuity plans, and develop suppliers when market capability is strategically important.", "children": [{"id": "0ea6e880-648d-40c1-a23a-fa4a5b43176b", "type": "subtopic", "title": "Supplier risk management", "children": [{"id": "1167aefe-71a7-4153-acae-e71968b42821", "type": "concept", "title": "Financial, operational, quality, cyber, ESG, and geopolitical risk"}, {"id": "ba287721-560c-4ff4-9e4d-86927cfc56fe", "type": "concept", "title": "Critical supplier mapping"}, {"id": "4a03842b-5169-4e83-9bb8-8c1f64e4f077", "type": "concept", "title": "Risk scoring and heat maps"}, {"id": "129c92c5-4ae2-472e-8e67-b0be995ebc35", "type": "concept", "title": "Early-warning indicators"}], "description": "Supplier risk management identifies where dependence, fragility, or misconduct could damage the organization."}, {"id": "33b3642a-9e97-4c68-9d37-97fbdaf10891", "type": "subtopic", "title": "Continuity and resilience planning", "children": [{"id": "e142ee90-2dfe-44bc-a05f-ae4a3e1cb780", "type": "concept", "title": "Business continuity plans"}, {"id": "42186018-2da2-4b37-a34b-d0c78eb0a9ab", "type": "concept", "title": "Safety stock and buffer capacity"}, {"id": "3760c6be-ff84-4f49-a99c-db7b9886b8e8", "type": "concept", "title": "Alternate suppliers and substitution plans"}, {"id": "c485af77-5447-4ab3-a4a3-ae8e1d4b133f", "type": "concept", "title": "Scenario planning and stress testing"}], "description": "Resilience planning prepares the organization to absorb disruption and recover service faster."}, {"id": "a95dbe93-1745-4179-80a7-ee14266624d4", "type": "subtopic", "title": "Supplier development", "children": [{"id": "97e420e7-a74d-458f-b47a-595564378a7a", "type": "concept", "title": "Capability assessments"}, {"id": "eb86ae68-7964-4eea-9900-447e8f2d41a2", "type": "concept", "title": "Joint improvement roadmaps"}, {"id": "622c6ed1-87fd-485c-99a1-31cca869ab74", "type": "concept", "title": "Quality and process development"}, {"id": "6f168d58-74b2-4eee-91e8-d68d9693d472", "type": "concept", "title": "Exit, remediation, and escalation decisions"}], "description": "When markets cannot immediately provide the required capability, buyers may need to help suppliers improve."}]}, {"id": "cd9bdcb1-8ee7-44cf-b1b1-9c6864d09d97", "type": "topic", "title": "Capstone: Strategic Sourcing Project and Executive Recommendation", "description": "Apply the course end-to-end by diagnosing a category, building a sourcing strategy, evaluating options, and presenting an executive recommendation.", "children": [{"id": "e83766ec-76f7-4d4e-b6d7-617cf1b1a569", "type": "subtopic", "title": "Category diagnosis", "children": [{"id": "ecb4dfcc-5b4e-4e82-a870-753b592e0176", "type": "concept", "title": "Problem statement and scope"}, {"id": "1630c287-1c1d-4b5d-80e6-0bfdce60c44b", "type": "concept", "title": "Baseline spend and demand profile"}, {"id": "312d128c-beea-4324-af10-61ef5c808e5e", "type": "concept", "title": "Supplier and market analysis"}, {"id": "5bb052e9-b358-4bb2-b282-6537e419f0cd", "type": "concept", "title": "Stakeholder interviews"}], "description": "The capstone begins with evidence: spend, demand, market structure, supplier performance, risk, and stakeholder needs."}, {"id": "8948df02-fd1a-40a0-9b51-d4bb2f711ebd", "type": "subtopic", "title": "Sourcing strategy and business case", "children": [{"id": "c1790a06-4c9b-4a46-b970-0df557b4c9ef", "type": "concept", "title": "Sourcing levers and scenario options"}, {"id": "8498f1e3-40c5-4316-b940-e6228a1bd19b", "type": "concept", "title": "Savings and value model"}, {"id": "53d9a905-6d15-4434-9163-f5959c603d7d", "type": "concept", "title": "Risk and sustainability implications"}, {"id": "2a215d46-196d-4e16-9f78-51772e32cd0a", "type": "concept", "title": "Implementation timeline and governance"}], "description": "Students synthesize analysis into a sourcing strategy that is credible, quantified, and implementable."}, {"id": "0a62ec52-8af4-4368-ac9a-2c0a03938f02", "type": "subtopic", "title": "Executive recommendation", "children": [{"id": "0dcab368-5b76-4ba0-878a-556be2c5b753", "type": "concept", "title": "Executive summary and decision ask"}, {"id": "9efc5ba1-5975-448b-8a23-27eec7e7a3c0", "type": "concept", "title": "Evidence-backed tradeoffs"}, {"id": "2e092e16-6321-419c-a09c-4f931f2e0fdd", "type": "concept", "title": "Supplier award or negotiation plan"}, {"id": "6e18e85e-b4b5-4f6c-9981-473d13bccdbd", "type": "concept", "title": "Implementation risks and next steps"}], "description": "The final recommendation develops the communication discipline needed to persuade senior decision makers."}]}], "dbBacked": true}$procjson$::jsonb,
