update public.learning_paths
set
  title = 'Procurement and Sourcing',
  goal = 'Procurement and Sourcing',
  summary = 'The syllabus includes category management, market intelligence, total cost of ownership, RFx design, negotiation game planning, contract governance, global trade risk, responsible sourcing, digital procurement, supplier development, and a full strategic sourcing capstone.',
  data = $procjson${"slug": "procurement-and-sourcing", "title": "Procurement and Sourcing", "description": "The syllabus includes category management, market intelligence, total cost of ownership, RFx design, negotiation game planning, contract governance, global trade risk, responsible sourcing, digital procurement, supplier development, and a full strategic sourcing capstone.", "topics": [{"id": "d98db48b-e474-44c0-ac28-1e7a15f5f029", "type": "topic", "title": "Procurement and Strategic Sourcing as a Supply Chain Value System", "description": "Position procurement as a strategic capability that shapes cost, risk, innovation, resilience, sustainability, and customer value across the supply chain.", "children": [{"id": "780263c2-59a1-47b5-b856-9190946fd4c6", "type": "subtopic", "title": "Procurement's strategic role", "children": [{"id": "4405c768-a239-476c-a57e-db9f62594737", "type": "concept", "title": "Cost, quality, service, risk, innovation, and ESG value"}, {"id": "0e4a0e6e-f3e6-483f-aa3c-06a28a3f1513", "type": "concept", "title": "Procurement's links to operations, finance, legal, engineering, and sustainability"}, {"id": "282b902f-ea09-4785-aaff-77cd8a4d9d65", "type": "concept", "title": "Source-to-pay versus strategic sourcing"}, {"id": "f98089a7-8e50-4237-9a1b-8fe12b2867b5", "type": "concept", "title": "Procurement as a supply-chain coordination function"}], "description": "This subtopic reframes procurement from transaction handling into a leadership function that can shape enterprise outcomes."}, {"id": "d11ab77b-127f-4b1f-bbf2-60cd9a54b04a", "type": "subtopic", "title": "Supply-chain value architecture", "children": [{"id": "d2e98673-3e99-47a5-a142-74071f2aeb0e", "type": "concept", "title": "Plan-source-make-deliver-return logic"}, {"id": "84e98b9f-fb35-4e91-8c94-d1fcf1c77a90", "type": "concept", "title": "Supplier tiering and upstream dependencies"}, {"id": "677e8c3e-eebe-4f02-a793-ef1e256960b5", "type": "concept", "title": "Cost-service-resilience tradeoffs"}, {"id": "9a72298c-a4de-4983-8573-bd1f1b9bac88", "type": "concept", "title": "Value stream and process mapping"}], "description": "Students learn how sourcing decisions influence the wider supply chain, not just the price paid to a vendor."}, {"id": "2827b183-b15d-4c27-870c-68a1065253f4", "type": "subtopic", "title": "Governance and maturity", "children": [{"id": "497b3158-9aba-41e9-9862-0dd985840234", "type": "concept", "title": "Policy, delegation of authority, and approval thresholds"}, {"id": "5f1f8884-f141-45bb-a5f1-f95d68b37ee9", "type": "concept", "title": "Center-led, centralized, decentralized, and hybrid models"}, {"id": "5458e1fe-71ea-4743-9553-7386a739628b", "type": "concept", "title": "Procurement KPIs and scorecards"}, {"id": "98fd652b-54b4-433a-a4d1-e5773ccc4b07", "type": "concept", "title": "Stakeholder trust and service-level expectations"}], "description": "Procurement maturity models help students diagnose whether an organization is reactive, controlled, strategic, or transformational."}]}, {"id": "73884114-ded5-4742-ad7c-08158e4982d4", "type": "topic", "title": "Purchasing Process, Procure-to-Pay, and Procurement Operating Models", "description": "Build fluency in the process architecture that turns business needs into compliant purchases, payment, controls, and measurable service.", "children": [{"id": "3849eec2-8a7f-48d5-b6e6-8f7c5c287c73", "type": "subtopic", "title": "Purchasing workflow", "children": [{"id": "91b99425-008d-4b4f-9961-b7f808d75956", "type": "concept", "title": "Requisitions and approvals"}, {"id": "55e35b1e-09a8-4198-a63c-8008bfdb644c", "type": "concept", "title": "Purchase orders and blanket orders"}, {"id": "08f42787-f76b-4dff-901e-6466fd43ec97", "type": "concept", "title": "Receiving, three-way match, and invoice handling"}, {"id": "d8e0c3cc-0c51-488b-980d-53606d31d9f6", "type": "concept", "title": "Exception management and cycle-time control"}], "description": "The basic workflow shows how business requests become purchase orders, receipts, invoices, and payment."}, {"id": "43575a62-3663-43aa-946a-79635136b675", "type": "subtopic", "title": "Procure-to-pay controls", "children": [{"id": "9e9c4c1c-bd8b-4c98-839d-45cb505ce81a", "type": "concept", "title": "Segregation of duties"}, {"id": "706d13e0-0a3b-4145-8358-1a462feaefc2", "type": "concept", "title": "Preferred supplier and catalog compliance"}, {"id": "223eb226-7a76-47b8-805d-50ec7131e2e7", "type": "concept", "title": "Audit trails and documentation"}, {"id": "7d6b33e3-6fac-49e4-bef1-80fd9261673f", "type": "concept", "title": "Fraud red flags and internal control testing"}], "description": "Controls protect the organization from fraud, maverick spend, policy violations, and weak financial discipline."}, {"id": "51b10b12-512a-4ff3-8c9a-13d88c34e560", "type": "subtopic", "title": "Operating models and service design", "children": [{"id": "dc73f362-b333-4dfa-aebe-bb671b2c2cf2", "type": "concept", "title": "Category teams and business partnering"}, {"id": "bc24c4e4-9909-498d-99e2-b78f3061ac8d", "type": "concept", "title": "Shared services and help desks"}, {"id": "2ee56ebc-6b47-4122-a8f4-f10698ef59eb", "type": "concept", "title": "Centers of excellence"}, {"id": "090ef8ed-bc0e-4403-bcd1-68ec1b1d1a6b", "type": "concept", "title": "Service-level agreements and intake channels"}], "description": "Operating model choices determine how procurement serves business units while maintaining consistency and expertise."}]}, {"id": "32d3f9aa-2108-45eb-9794-42562e5da6fb", "type": "topic", "title": "Spend Analysis, Category Management, and Opportunity Assessment", "description": "Use data to understand what the organization buys, who it buys from, where value leaks occur, and which categories deserve focused sourcing attention.", "children": [{"id": "ccedb066-8437-45e2-ab03-b54e0501a593", "type": "subtopic", "title": "Spend visibility", "children": [{"id": "abd58693-3030-4dd9-bc45-22b4fc2db85d", "type": "concept", "title": "Data extraction and cleansing"}, {"id": "911959b3-18ba-4b76-aa21-42a3d83edb70", "type": "concept", "title": "Supplier normalization"}, {"id": "9b3b9cef-8239-4d89-b5fd-cffd1aeab273", "type": "concept", "title": "Commodity and UNSPSC-style classification"}, {"id": "2bfb530b-2adb-4363-a31c-053b8de036ec", "type": "concept", "title": "Tail spend and maverick spend"}], "description": "Spend visibility is the evidence base for nearly every serious sourcing decision."}, {"id": "e974dba4-2bc7-4f66-9c48-6d22f5f3ceb0", "type": "subtopic", "title": "Category strategy", "children": [{"id": "6ba1240a-0280-4be3-b19b-90703080bf0f", "type": "concept", "title": "Category profiling"}, {"id": "bfedc042-76af-4bbc-97b5-4b9c30516193", "type": "concept", "title": "Demand analysis and stakeholder mapping"}, {"id": "5ea054f1-07df-45e8-971b-56cb93767fb7", "type": "concept", "title": "Kraljic-style portfolio thinking"}, {"id": "5d586f33-4fe4-4998-8837-0e1504b08c72", "type": "concept", "title": "Strategic, leverage, bottleneck, and routine categories"}], "description": "Category management groups purchases into markets with similar suppliers, demand patterns, risks, and value levers."}, {"id": "149897b5-d380-4978-b737-73e6edc690b3", "type": "subtopic", "title": "Opportunity assessment", "children": [{"id": "95498de9-199b-4ee3-b7a1-1a67128db7a9", "type": "concept", "title": "Baseline spend and savings logic"}, {"id": "dc2dc922-be12-4ea9-810f-7b7a67f57de5", "type": "concept", "title": "Price, demand, specification, process, and compliance levers"}, {"id": "e785bb97-1eac-43e7-891b-3d31fc3bc01b", "type": "concept", "title": "Savings validation with finance"}, {"id": "7592aaeb-4475-43dd-a1f0-f6c324ecf4fb", "type": "concept", "title": "Opportunity pipeline and wave planning"}], "description": "Opportunity assessment helps prioritize sourcing work by value, feasibility, urgency, and organizational readiness."}]}, {"id": "d7772c68-7b6e-414e-9a8a-10219514cc0c", "type": "topic", "title": "Supplier Markets, Market Intelligence, and Make-Buy Decisions", "description": "Analyze supply markets, industry structure, supplier economics, and internal capability choices before launching sourcing work.", "children": [{"id": "bdc1a0ee-e086-47fd-babc-5d8ed0a4ca80", "type": "subtopic", "title": "Supply-market analysis", "children": [{"id": "3d8a7730-3161-4383-b4f1-cefe54d3e993", "type": "concept", "title": "Supplier landscape and market concentration"}, {"id": "1c3f85cb-6a3a-449b-b64d-accddc181a8c", "type": "concept", "title": "Porter's five forces for supply markets"}, {"id": "09ccfddc-9381-49a1-98ef-74b1541ccc22", "type": "concept", "title": "Capacity, lead time, and technology trends"}, {"id": "ce4ef20c-dd51-452e-ae10-fb61d4bf458e", "type": "concept", "title": "Commodity indices and market signals"}], "description": "Students learn to read supplier markets before assuming competition, capacity, or price power exists."}, {"id": "d37d4ac1-2801-456b-b498-1e2693a3b717", "type": "subtopic", "title": "Supplier economics", "children": [{"id": "19736f7f-06b7-47f4-a9cd-c7738e570213", "type": "concept", "title": "Cost structure and margin logic"}, {"id": "d418d4cf-0ffd-45f2-8214-c00a8381d089", "type": "concept", "title": "Fixed versus variable cost"}, {"id": "7ad19c35-d1f5-4a0f-bb89-101437bdb417", "type": "concept", "title": "Learning curves and scale effects"}, {"id": "8f9f58a3-05ef-492d-9699-fed376908e53", "type": "concept", "title": "Supplier financial health"}], "description": "Understanding supplier economics helps buyers negotiate realistically and build offers that can be sustained."}, {"id": "2717f6a0-278c-49ed-bd4d-20c9032e13f4", "type": "subtopic", "title": "Make-buy and outsourcing choices", "children": [{"id": "d702d28c-69d9-4430-9f05-0db60e494a24", "type": "concept", "title": "Core competence and strategic control"}, {"id": "e207faad-0af4-4b56-99a8-f53850b911ca", "type": "concept", "title": "Transaction-cost economics"}, {"id": "a4226819-04ac-42bd-b6dc-6971a78481b1", "type": "concept", "title": "Capacity, quality, and intellectual property concerns"}, {"id": "6a262618-f6a5-48bf-b25b-bb0b696e50d1", "type": "concept", "title": "Outsourcing, insourcing, and co-sourcing models"}], "description": "Make-buy decisions clarify what should remain internal, what can be outsourced, and what capabilities require close governance."}]}, {"id": "b78f818e-0a67-46c5-af41-99a61a2b3625", "type": "topic", "title": "Requirements, Specifications, and Total Cost of Ownership", "description": "Translate stakeholder needs into clear specifications and complete cost models that support smarter commercial decisions.", "children": [{"id": "68881a4e-ce74-4709-b2f1-cfb0485da67b", "type": "subtopic", "title": "Requirements discovery", "children": [{"id": "0f82ac60-015e-4c51-89cc-2abd1e92e606", "type": "concept", "title": "Voice of stakeholder and voice of customer"}, {"id": "9a1498f3-fb96-44fa-bd6f-a454f2677b03", "type": "concept", "title": "Functional versus technical requirements"}, {"id": "cfd184f8-ce64-4e61-ad8f-02b300692d45", "type": "concept", "title": "Service levels and performance outcomes"}, {"id": "efefe2a7-1569-487a-8c23-194870bd385e", "type": "concept", "title": "Demand management and standardization"}], "description": "Good sourcing starts with understanding the real business need, not merely repeating last year's specification."}, {"id": "ced4b326-c754-41fb-99ec-1d9d511d2627", "type": "subtopic", "title": "Specification strategy", "children": [{"id": "eb13837a-5515-4ef8-9bba-2f10ab3725d1", "type": "concept", "title": "Design specifications"}, {"id": "db92e050-331d-4bbb-ae85-ce7b1ca303b5", "type": "concept", "title": "Performance specifications"}, {"id": "d2ec231f-d86e-4880-9536-ea6f6651c6c9", "type": "concept", "title": "Statements of work"}, {"id": "eb964347-21fc-483d-99bd-542cd8966a98", "type": "concept", "title": "Specification lock-in and over-specification"}], "description": "Specification choices influence competition, innovation, cost, and supplier accountability."}, {"id": "f85115f1-f1b3-42c5-8c73-d8dd810d20c8", "type": "subtopic", "title": "Total cost of ownership", "children": [{"id": "5bd309f8-d0bf-4d71-99e5-cbae78eb67e6", "type": "concept", "title": "Acquisition, operating, maintenance, logistics, quality, and disposal costs"}, {"id": "10a4c465-6515-413e-bbcd-95cece59fc93", "type": "concept", "title": "Switching costs and transition costs"}, {"id": "3089eba2-2c11-42d0-bfec-d3ed0bda4c6b", "type": "concept", "title": "Landed cost and tariff effects"}, {"id": "62d6a64b-87ab-4c26-8c8f-7ba239f3c2fa", "type": "concept", "title": "Cost sensitivity and scenario analysis"}], "description": "TCO prevents teams from mistaking the lowest unit price for the best business decision."}]}, {"id": "cdf9e4f4-08e7-4c02-b787-b3a815a4c89c", "type": "topic", "title": "Supplier Identification, Qualification, and Selection", "description": "Develop disciplined methods for finding, screening, evaluating, and selecting suppliers that fit cost, quality, risk, and strategic goals.", "children": [{"id": "6642cd8a-132b-4333-8b83-918a84b96bab", "type": "subtopic", "title": "Supplier discovery", "children": [{"id": "03b83d61-288f-4cf9-a30e-3a6e07c23e85", "type": "concept", "title": "Incumbents and challengers"}, {"id": "735c5970-e544-461e-bdf0-48f719ac6661", "type": "concept", "title": "Supplier databases and industry networks"}, {"id": "3ffd2cf0-9147-4126-9ded-cbe66d92d58b", "type": "concept", "title": "Diverse and local supplier discovery"}, {"id": "8d3ed460-1279-4522-9d24-e8ceb5ed80ee", "type": "concept", "title": "Long lists, short lists, and market sounding"}], "description": "Supplier discovery builds the candidate pool and determines whether the organization sees the full market."}, {"id": "186f1631-6baf-44cd-beec-1670a9350378", "type": "subtopic", "title": "Qualification and due diligence", "children": [{"id": "9219267b-93a3-4633-ae1c-8b5703c03d43", "type": "concept", "title": "Financial, operational, quality, and capacity checks"}, {"i